import{_ as a,o,c as s,a2 as n}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Solución de problemas","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/troubleshooting.md","filePath":"es-ES/user-guide/troubleshooting.md","lastUpdated":1787586465000}'),r={name:"es-ES/user-guide/troubleshooting.md"};function t(i,e,l,d,c,u){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to &quot;Solución de problemas&quot;">​</a></h1><p>¿Tienes dificultades al usar Lertaro? Sigue estos pasos sistemáticos para identificar y resolver las causas más comunes.</p><h2 id="_1-los-atajos-globales-no-responden" tabindex="-1">1. Los atajos globales no responden <a class="header-anchor" href="#_1-los-atajos-globales-no-responden" aria-label="Permalink to &quot;1. Los atajos globales no responden&quot;">​</a></h2><ul><li><strong>Comprobar el estado del servicio</strong>: Accede a <a href="./settings/service-status.html"><strong>Configuración → Estado del servicio</strong></a> y confirma que <code>Lertaro.Service</code> está en ejecución. Aunque los atajos ordinarios los gestiona la App, el proceso elevado de intercepción depende del servicio.</li><li><strong>Aislamiento de privilegios (UIPI)</strong>: Si la ventana en primer plano se ejecuta como administrador (p. ej., símbolo del sistema o Administrador de tareas elevados), Windows bloquea la intercepción de teclas desde procesos estándar. Lertaro eleva automáticamente su interceptor; asegúrate de que el servicio esté activo.</li><li><strong>Revisar la lista negra de procesos</strong>: En <a href="./settings/hotkeys-page.html#lista-negra-de-procesos"><strong>Configuración → Atajos de teclado</strong></a>, comprueba si la aplicación activa está en la lista negra. Lertaro ignora intencionadamente los atajos mientras estas apps están en primer plano.</li><li><strong>Omisión en juegos y apps a pantalla completa</strong>: Con juegos 3D o reproductores a pantalla completa exclusiva, los atajos se omiten por defecto para no interferir. Activa <strong>Responder al enfocar aplicaciones a pantalla completa</strong> en <strong>Configuración → Atajos de teclado</strong> si prefieres que respondan siempre.</li></ul><h2 id="_2-los-resultados-estan-desactualizados-o-incompletos" tabindex="-1">2. Los resultados están desactualizados o incompletos <a class="header-anchor" href="#_2-los-resultados-estan-desactualizados-o-incompletos" aria-label="Permalink to &quot;2. Los resultados están desactualizados o incompletos&quot;">​</a></h2><ul><li><strong>Unidades NTFS / ReFS locales</strong>: Se actualizan casi en tiempo real leyendo el diario de cambios USN del sistema de archivos.</li><li><strong>Unidades FAT32 / exFAT</strong>: Se supervisan continuamente mediante eventos de cambio del sistema de archivos.</li><li><strong>Reconstrucción manual</strong>: Si un corte de energía provocó inconsistencias en el índice, ve a <a href="./settings/index-drives.html"><strong>Configuración → Indexación → Unidades locales</strong></a> y pulsa <strong>Reconstruir índice</strong> en la unidad afectada.</li></ul><h2 id="_3-las-unidades-de-red-no-se-actualizan" tabindex="-1">3. Las unidades de red no se actualizan <a class="header-anchor" href="#_3-las-unidades-de-red-no-se-actualizan" aria-label="Permalink to &quot;3. Las unidades de red no se actualizan&quot;">​</a></h2><ul><li><strong>Escaneo periódico</strong>: Los recursos de red compartidos (SMB / NAS) carecen de diario USN local y dependen de sondeos programados.</li><li><strong>Comprobar el modo de actualización</strong>: En <a href="./settings/index-drives.html#unidades-de-red"><strong>Configuración → Indexación → Unidades de red</strong></a>, verifica que no esté en modo &quot;Manual&quot;.</li><li><strong>Protección contra bucles de enlaces simbólicos</strong>: Lertaro incluye detección de bucles para evitar bloqueos por enlaces recursivos en carpetas NAS.</li></ul><h2 id="_4-un-archivo-o-carpeta-no-aparece-en-las-busquedas" tabindex="-1">4. Un archivo o carpeta no aparece en las búsquedas <a class="header-anchor" href="#_4-un-archivo-o-carpeta-no-aparece-en-las-busquedas" aria-label="Permalink to &quot;4. Un archivo o carpeta no aparece en las búsquedas&quot;">​</a></h2><ul><li><strong>Revisar reglas de exclusión</strong>: Ve a <a href="./settings/index-drives.html#reglas-de-exclusión"><strong>Configuración → Indexación → Reglas de exclusión</strong></a> y confirma que no esté excluido por ruta exacta, comodines o expresiones regulares.</li><li><strong>Comprobar activación de unidad</strong>: En <a href="./settings/index-drives.html"><strong>Configuración → Indexación → Unidades locales</strong></a>, confirma que la unidad esté habilitada.</li></ul><h2 id="_5-el-menu-de-candidatos-ime-no-aparece-en-la-ventana-incrustada" tabindex="-1">5. El menú de candidatos IME no aparece en la Ventana incrustada <a class="header-anchor" href="#_5-el-menu-de-candidatos-ime-no-aparece-en-la-ventana-incrustada" aria-label="Permalink to &quot;5. El menú de candidatos IME no aparece en la Ventana incrustada&quot;">​</a></h2><ul><li><strong>Diseño sin foco</strong>: La <a href="./getting-started.html#3-tres-modalidades-de-ventana">Ventana incrustada</a> no toma el foco del teclado para evitar parpadeos al cerrarse. Dado que los menús de candidatos de ciertos métodos de entrada (IME) requieren foco real de ventana, pueden no mostrarse en modo incrustado.</li><li><strong>Solución recomendada</strong>: Usa la Ventana rápida (doble pulsación de <code>Ctrl</code>), la cual cuenta con foco completo.</li></ul><h2 id="_6-consulta-de-registros-y-reporte-de-errores" tabindex="-1">6. Consulta de registros y reporte de errores <a class="header-anchor" href="#_6-consulta-de-registros-y-reporte-de-errores" aria-label="Permalink to &quot;6. Consulta de registros y reporte de errores&quot;">​</a></h2><p>Si el problema persiste, revisa los registros en <a href="./settings/service-status.html"><strong>Configuración → Estado del servicio</strong></a>:</p><ul><li><strong>Registros de Service</strong>: Indexación, diarios USN, escaneos de red y comunicación IPC.</li><li><strong>Registros de App</strong>: Renderizado de interfaz, plugins, atajos y cambios de configuración.</li><li><strong>Registros de Hook</strong>: Intercepción de teclado y gestos de ratón.</li></ul><p>Filtra por palabras clave o nivel de gravedad (Info / Warn / Error) antes de adjuntar los registros a un issue en GitHub.</p>',16)])])}const m=a(r,[["render",t]]);export{g as __pageData,m as default};
